import { NetCityModalController } from "approot/global/controllers/netcityModalCtrl";

export class PublishInfoCtrl extends NetCityModalController {
	constructor(pageContext, $scope, $http, $alerts, $dialogs, $uibModalInstance, work, publishInfo, changeTracker) {
		super($scope, $uibModalInstance, changeTracker, $dialogs);

		this.$uibModalInstance = $uibModalInstance;
		this.$http = $http;
		this.$alerts = $alerts;
		this.header = "Информация о публикации";
		this.language = language;
		this.data = {
			diagnosticWork: work,
			publishInfo: publishInfo ? publishInfo.clientsPublishInfo : null
		};
		this.ready = false;
		this.$http.get("/webapi/references/publishStatuses").then((result) => {
			this.data.publishStatuses = result.data;
			this.data.publishStatusesDictionary = _.object(_.pluck(this.data.publishStatuses, "key"), _.pluck(this.data.publishStatuses, "name"));
			if (!this.data.publishInfo) {
				this.$http.get("/webapi/diagnosticWorks/region/publishInfo", { params: { diagnosticWorkId: work.id } })
					.then((info) => {
						this.data.publishInfo = info.data.clientsPublishInfo;
						let existsNotPublished = this.data.publishInfo && _.some(this.data.publishInfo, (item) => !item.success);
						work.regionalPublishedCondition = existsNotPublished ? "ExistsNotPublished" : "AllPublished";
						this.setAuxData();
						this.ready = true;
					})
					.catch((error) => {
						this.data.publishInfo = [];
						this.ready = true;
						this.$alerts.error(error.data.message, error.data.details);
					});
			} else {
				this.setAuxData();
				this.ready = true;
			}
		});
	}

	cancel() {
		this.$uibModalInstance.dismiss('cancel');
	}

	setAuxData() {
		if (this.data.publishInfo) {
			_.each(this.data.publishInfo, (item) => {
				item.publishTimeStr = item.publishTime
					? dateUtils.date2str(new Date(item.publishTime)) + " " + dateUtils.time2str(new Date(item.publishTime))
					: "";
				item.publishStatusInfo = this.data.publishStatusesDictionary[item.status];
			});
		}
	}
}

PublishInfoCtrl.$inject = ["pageContext", "$scope", "$http", "$alerts", "$dialogs", "$uibModalInstance", "work", "publishInfo", "changeTracker"];



