import { NetCityModalController } from "approot/global/controllers/netcityModalCtrl";

export class RestrictionsInfoCtrl extends NetCityModalController {
	constructor($scope, $http, $alerts, $dialogs, $uibModalInstance, info, title, comment, changeTracker) {
		super($scope, $uibModalInstance, changeTracker, $dialogs);

		this.$uibModalInstance = $uibModalInstance;
		this.$http = $http;
		this.$alerts = $alerts;
		this.header = title;
		this.language = language;
		this.data = {
			info: info,
			comment: comment
		};
	}

	cancel() {
		this.$uibModalInstance.dismiss('cancel');
	}

}

RestrictionsInfoCtrl.$inject = ["$scope", "$http", "$alerts", "$dialogs", "$uibModalInstance", "info", "title", "comment", "changeTracker"];



