import { NetCityModalController } from "approot/global/controllers/netcityModalCtrl";

export class EditVariantCtrl extends NetCityModalController {
	constructor(pageContext, $scope, $http, $alerts, $dialogs, $uibModalInstance, model, changeTracker) {
		super($scope, $uibModalInstance, changeTracker, $dialogs);

		this.appointedTypes = [
			{ id: -1, name: "всем" },
			{ id: 0, name: "школам" },
			{ id: 1, name: "муниципалитетам" }
		];
		this.$uibModalInstance = $uibModalInstance;
		this.$http = $http;
		this.$alerts = $alerts;
		this.$dialogs = $dialogs;
		this.header = "Создание/редактирование варианта диагностической работы";
		this.language = language;
		this.data = {
				variant: model.variant,
				diagnosticWork: model.diagnosticWork,
				appointedTypes: this.appointedTypes,
				schools: [],
				founders: []
		};
		this.ready = false;

		this.foundersRequest = this.$http.get("/webapi/em/founders")
				.then((response) => {
						return this.data.founders = response.data;
					}
				);

		this.schoolsRequest = this.$http.get("/webapi/em/schoolsByFuncType/2")
				.then((response) => {
						return this.data.schools = response.data;
					}
				);

		this.defaultCatch = (response) => {
			if (response && response.data) {
				$.show.error(response.data.message || this.language.Generic.Common.kErrorMsg);
			} else {
				$.show.error(this.language.Generic.Common.kErrorMsg);
			}
		};

		this.wrapToPromise = function (request) {
			return new Promise(function(resolve, reject) {
				return request
						.then(resolve)
						.catch(reject);
			});
		};

		$.when.apply($, [this.wrapToPromise(this.foundersRequest), this.wrapToPromise(this.schoolsRequest)])
			.done(() => this.ready = true)
			.fail(this.defaultCatch);
	}

	cancel() {
		this.$uibModalInstance.dismiss('cancel');
	}

	showAppointedSchools() {
		return this.data.variant.appointedType.id === 0; //Тип назначения "школам"
	}

	showAppointedMunicipalities() {
		return this.data.variant.appointedType.id === 1; //Тип назначения "муниципалитетам"
	}

	validate() {
		if (!this.data.variant.name) {
			this.$dialogs.message("Наименование не может быть пустым");
			return false;
		}
		if (this.data.variant.appointedType.id === 0 && this.data.variant.schools.length <= 0) {
			this.$dialogs.message("Выберите школы для назначения");
			return false;
		}
		if (this.data.variant.appointedType.id === 1 && this.data.variant.founders.length <= 0) {
			this.$dialogs.message("Выберите муниципалитет для назначения");
			return false;
		}
		return true;
	}

	ok() {
		if (this.data.variant.appointedType.id === 0) {
			this.data.variant.founders = [];
		}
		if (this.data.variant.appointedType.id === 1) {
			this.data.variant.schools = [];
		}
		let dwVariant = _.pick(this.data.variant, 'id', 'name', 'testPlanId', 'schools', 'appointedType', 'founders');
		dwVariant.diagnosticWork = _.pick(this.data.variant.diagnosticWork, 'id', 'name');
		if (!this.validate()) {
			return;
		}
		this.$http.post("/webapi/diagnosticWorks/variants", dwVariant)
			.then((response) => {
				this.$uibModalInstance.close(response.data);
				this.$alerts.success("Сохранен вариант");
			})
			.catch((response) => this.$alerts.error(response.data.message || response.data.details));
	}
}

EditVariantCtrl.$inject = ["pageContext", "$scope", "$http", "$alerts", "$dialogs", "$uibModalInstance", "model", "changeTracker"];



