const module = angular.module("irtech.netcity.em.diagnosticworks",
	[
		'ngFileUpload', 'ngRoute', 'ngSanitize', 'ngMessages', 'ui.select', 'uikit.alerts', 'uikit.dialogs', 'ui.bootstrap',
		'irtech.netcity.directive', "irtech.netcity.common", "irtech.netcity.ui-components"
	]);

require("approot/global/directives/storageDirective.coffee");
import { DiagnosticWorksListCtrl } from "./list/diagnosticWorksListCtrl.js";
import { PublishInfoCtrl } from "./info/publishInfoCtrl.js";
import { RestrictionsInfoCtrl } from "./info/restrictionsInfoCtrl.js";
import { EditVariantCtrl } from "./editVariant/editVariantCtrl.js";
import { DiagnosticWorkCtrl } from "./edit/editDiagnosticWorkCtrl.js";
import { EditDateRangeComponent } from "approot/global/components/dateInput.component.ts";

module
	.component("editDateRangeComponent", EditDateRangeComponent)
	.controller("DiagnosticWorksListCtrl", DiagnosticWorksListCtrl)
	.controller("EditVariantCtrl", EditVariantCtrl)
	.controller("PublishInfoCtrl", PublishInfoCtrl)
	.controller("RestrictionsInfoCtrl", RestrictionsInfoCtrl)
	.controller("DiagnosticWorkCtrl", DiagnosticWorkCtrl)
	.filter('propsFilter', function() {
		return function(items, props) {
			var out;
			out = [];
			if (angular.isArray(items)) {
				items.forEach(function(item) {
					var i, itemMatches, keys, len, prop, text;
					itemMatches = false;
					keys = Object.keys(props);
					for (i = 0, len = keys.length; i < len; i++) {
						prop = keys[i];
						text = props[prop].toLowerCase();
						if (item[prop].toString().toLowerCase().indexOf(text) !== -1) {
							itemMatches = true;
							break;
						}
					}
					if (itemMatches) {
						return out.push(item);
					}
				});
			} else {
				out = items;
			}
			return out;
		};
	})
	.config(function($routeProvider, $locationProvider) {
		$routeProvider.otherwise({
			redirectTo: '/',
			templateUrl: '/static/dist/app/em/diagnosticworks/list/template.html',
			controller: 'DiagnosticWorksListCtrl as ctrl'
		});
		return $locationProvider.html5Mode(true);
	});



