import Selectable from "approot/global/selectable";
import gradeConstants from "webroot/static/src/pages/grade/js/journal-constants.js";

class DiagnosticWorksListCtrl {
	constructor(pageContext, $appLoader, $http, $alerts, $uibModal, $longWork, $dialogs, $q, settingsProvider) {
		this.language = language;
		this.$alerts = $alerts;
		this.$http = $http;
		this.$dialogs = $dialogs;
		this.$appLoader = $appLoader;
		this.$uibModal = $uibModal;
		pageContext.title = "Диагностические работы";
		pageContext.parent = null;
		this.viewReady = false;
		this.tableReady = false;
		this.state = { readOnly: false, regional: false };
		this.data = {
			globalYears: [],
			globalYear: null,
			subjects: [],
			subject: null,
			testLevels: [],
			testLevel: null,
			testLevelsDictionary: null,
			responseSubjects: [],
			responseTestLevels: [],
			diagnosticWorks: [],
			diagnosticWork: new DiagnosticWork(),
			variant: new Variant(),
			defaultVal: { id: -1 },
			name: "Все",
			idSelected: [],
			selection: new Selectable(),
			publishing: false
		};
		this.urls = {
			year: "/webapi/em/years?main=true",
			subjects: "/webapi/references/subjectFipi",
			testLevels: "/webapi/references/testLevels"
		};

		this.loader = {
			getGlobalYears: () => this.$http.get("/webapi/em/years"),
			getDiagnosticWorks: (yearId, subjectId, testLevel) => {
				let params = { yearId, subjectId, testLevel };
				return this.$http.get("/webapi/diagnosticWorks", { params: params });
			}
		};

		this.initingFilters = true;
		let promise = [];

		promise.push(
			settingsProvider.ServerSettings.SystemSettings.IsRegionEMForSchool().then((val) => {
				if (val) {
					this.state.regional = true;
				}
				this.$http.get(this.urls.testLevels)
					.then((response) => {
						this.data.responseTestLevels = angular.copy(response.data);
						this.data.testLevelsDictionary = _.object(_.pluck(this.data.responseTestLevels, "id"), _.pluck(this.data.responseTestLevels, "name"));
						if (this.state.regional) {
							this.data.responseTestLevels = _.filter(this.data.responseTestLevels, (item) => this.isRegionalLevel(item.id));
						}
						this.data.testLevels = angular.copy(response.data);
						if (this.state.regional) {
							this.data.testLevels = _.filter(this.data.testLevels, (item) => this.isRegionalLevel(item.id));
						}
						this.data.testLevels.unshift({ id: -1, name: "Все" });
					})
					.catch(this.alterErrorHandler);

			})
		);

		promise.push(
			this.$http.get(this.urls.subjects)
				.then((response) => {
					// создается клон массива предметов, для того чтоб передать в диалоговое окно массив без параметра "Все"
					this.data.responseSubjects = angular.copy(response.data);
					response.data.unshift({ id: -1, name: "Все" });
					this.data.subjects = response.data;
				})
				.catch(this.alterErrorHandler)
		);

		promise.push(
			this.loader.getGlobalYears()
				.then((response) => {
					this.data.globalYears = response.data;
					if (!this.data.globalYears || !this.data.globalYears.length) {
						this.criticalError = "Страница недоступна из-за того, что с данным управлением образования не связано ни одного образовательного учреждения, либо в связанных учреждения не пройден мастер ввода данных";
					}
					if (!this.data.globalYear) {
						this.data.globalYear = _.first(this.data.globalYears);
					}
				})
				.catch(this.alterErrorHandler)
		);

		//Загрузка страницы
		this.$appLoader.show();
		$q.all(promise).then(() => {
			this.$appLoader.hide();
			this.viewReady = true;
			this.updateTable();
		});
	}

	modalDiagnosticWork(diagnosticWork) {
		let modalInstance = this.$uibModal.open({
			templateUrl: '/static/dist/app/em/diagnosticworks/edit/template.html',
			controller: 'DiagnosticWorkCtrl as ctrl',
			size: "lg",
			resolve: {
				model: () => {
					return {
						diagnosticWork: diagnosticWork,
						subjects: _.clone(this.data.responseSubjects),
						testLevels: _.clone(this.data.responseTestLevels)
					};
				},
				work: () => diagnosticWork
			}
		});

		modalInstance.result.then(() => {
			this.clearSelection();
			this.updateTable();
		});
	}

	//добавить диагностическую работу
	addDiagnosticWork() {
		if (this.data.globalYear.id === -1) {
			this.$dialogs.message("Пожалуйста, выберите учебный год");
			return;
		}
		let diagnosticWork = new DiagnosticWork();
		diagnosticWork.subjectFipi = this.data.subject;
		diagnosticWork.globalYearId = this.data.globalYear.id;
		this.modalDiagnosticWork(diagnosticWork);
		return;
	}

	//редактировать диагностическую работу
	editDiagnosticWork(diagnosticWork) {
		this.modalDiagnosticWork(angular.copy(diagnosticWork));
	}

	isRegionalLevel(level) {
		return level === 1 || level === 4 || level === 5;
	}

	isRegionalLevelWork(diagnosticWork) {
		return diagnosticWork && this.isRegionalLevel(diagnosticWork.testLevel);
	}

	isReadOnlyWork(diagnosticWork) {
		return diagnosticWork && (this.state.readOnly || (this.state.regional && (!this.isRegionalLevelWork(diagnosticWork) || !diagnosticWork.regionGuid)));
	}

	isExistsTestTasksInAllVariants(diagnosticWork) {
		return diagnosticWork && _.every(diagnosticWork.variants, (item) => item.testTasksAmount);
	}

	closeProcessing() {
		if (this.processing) {
			this.processing.close();
		}
	}

	defaultHandler(response) {
		this.data.publishing = false;
		this.closeProcessing();
		this.$appLoader.hide();
		this.$alerts.error(response.data.message, response.data.details);
	}

	isVpr(diagnosticWork) {
		return diagnosticWork && diagnosticWork.testLevel === 4;
	}

	//Опубликовать
	publish(diagnosticWork) {
		let post = () => {
			this.data.publishing = true;
			this.processing = $.show.processing();
			if (this.state.regional && diagnosticWork.regionGuid) {
				this.$http.post("/webapi/diagnosticWorks/region/publish", diagnosticWork.id)
					.then((result) => {
						this.closeProcessing();
						this.data.publishing = false;
						let existsNotPublished = result && result.data && result.data.clientsPublishInfo && _.some(result.data.clientsPublishInfo, (item) => !item.success);
						diagnosticWork.regionalPublishedCondition = existsNotPublished ? "ExistsNotPublished" : "AllPublished";
						if (diagnosticWork.regionalPublishedCondition == 'ExistsNotPublished') {
							diagnosticWork.published = true;
							this.$alerts.error("Диагностическая работа опубликована не во всех учебных заведениях");
						} else {
							this.successHandler("Диагностическая работа опубликована")();
						}
						
						this.publishInfo(diagnosticWork, result.data);
						this.clearSelection();
					})
					.catch((error) => this.defaultHandler(error));
			} else {
				this.$http.post("/webapi/diagnosticWorks/publish", [diagnosticWork.id])
					.then((result) => {
						this.closeProcessing();
						this.data.publishing = false;
						this.clearSelection();
						this.successHandler("Диагностическая работа опубликована")();
					})
					.catch((error) =>
						this.defaultHandler(error));
			}
		};
		this.$dialogs.confirm("Вы действительно желаете опубликовать выбранную диагностическую работу?").then(post);
	}

	//Сбросить выделение
	clearSelection() {
		if (this.data.selection) {
			this.data.selection.dropSelect();
		}
	}

	//Информация о публикации с регионального сервера
	publishInfo(diagnosticWork) {
		let modalInstance = this.$uibModal.open({
			templateUrl: '/static/dist/app/em/diagnosticworks/info/template.html',
			controller: 'PublishInfoCtrl as ctrl',
			size: "lg",
			resolve: {
				work: () => { return diagnosticWork; },
				publishInfo: () => null
			}
		});
		modalInstance.result.then(() => {});
	}

	//Отозвать публикации
	unpublish(diagnosticWork) {
		let post = () => {
			this.processing = $.show.processing();
			if (this.state.regional && diagnosticWork.regionGuid) {
				this.$http.get("/webapi/diagnosticWorks/linkedOrgs", { params: { diagnosticWorkId: diagnosticWork.id } })
					.then((result) => {
						if (result && !result.data) {
							this.$http.post("/webapi/diagnosticWorks/region/unpublish", diagnosticWork.id)
								.then((result) => {
									this.closeProcessing();
									if (result.data && result.data.clientsUnPublishInfo && _.every(result.data.clientsUnPublishInfo, (item) => item.success)) {
										this.clearSelection();
										this.successHandler("Публикация диагностической работы отозвана")();
									} else {
										let detailInfo = "";
										if (result.data && result.data.clientsUnPublishInfo) {
											let notSuccess = _.toArray(_.filter(result.data.clientsUnPublishInfo, (info) => !info.success));
											_.each(notSuccess, (item) => detailInfo = `${detailInfo}\n${item.clientName}: ${item.details}`);
											detailInfo = detailInfo.trim();
										} else {
											detailInfo = "Нет информационного ответа от сервера";
										}
										this.linkedOrgsInfo(detailInfo);
									}
								})
								.catch((error) => this.linkedOrgsInfo(error.data ? error.data.message + error.data.details : ""));
						} else {
							this.linkedOrgsInfo("Существуют следующие организации, в которых присутствует связь с диагностической работой:\n" + result.data);
						}
					})
					.catch((error) => this.defaultHandler(error));
			} else {
				this.$http.get("/webapi/diagnosticWorks/linkedOrgs", { params: { diagnosticWorkId: diagnosticWork.id } })
					.then((result) => {
						if (result && !result.data) {
							this.$http.post("/webapi/diagnosticWorks/unpublish", diagnosticWork.id)
								.then((result) => {
									this.closeProcessing();
									this.clearSelection();
									this.successHandler("Публикация диагностической работы отозвана")();
								})
								.catch((error) => this.linkedOrgsInfo(error.data ? error.data.message + error.data.details : ""));
						} else {
							this.linkedOrgsInfo(result.data);
						}
					})
					.catch((error) => this.defaultHandler(error));
			}
		};
		this.$dialogs.confirm("Вы действительно желаете отозвать публикацию выбранной диагностической работы?").then(post);
	}

	linkedOrgsInfo(info) {
		this.data.publishing = false;
		this.closeProcessing();
		this.$appLoader.hide();
		let modalInstance = this.$uibModal.open({
			templateUrl: '/static/dist/app/em/diagnosticworks/info/restrictionsInfoTemplate.html',
			controller: 'RestrictionsInfoCtrl as ctrl',
			size: "lg",
			resolve: {
				info: () => info,
				title: () => "Ошибка выполнения отзыва диагностической работы",
				comment: () => "Невозможно выполнить отзыв диагностической работы.\n"
			}
		});
		modalInstance.result.then(() => {});
	}


	//удалить диагностические работы
	removeDiagnosticWorks(diagnosticWork) {
		let deleteMessage = () => {
			this.$http.delete("/webapi/diagnosticWorks/", { params: { id: diagnosticWork.id } })
				.then(() => {
					this.clearSelection();
					this.successHandler("Диагностическая работа удалена")();
				})
				.catch((error) => this.defaultHandler(error));
		};
		this.$dialogs.confirm("Вы действительно желаете удалить выбранную диагностическую работу?").then(deleteMessage);
	}

	//добавить/редактировать вариант
	editVariant(diagnosticWork, variant) {
		if (!variant) {
			variant = new Variant();
			variant.diagnosticWork.id = diagnosticWork.id;
		}

		let modalInstance = this.$uibModal.open({
			templateUrl: '/static/dist/app/em/diagnosticworks/editVariant/template.html',
			controller: 'EditVariantCtrl as ctrl',
			size: "lg",
			resolve: {
				model: () => {
					return {
						diagnosticWork: _.clone(diagnosticWork),
						variant: _.clone(variant)
					};
				}
			}
		});

		modalInstance.result.then((response) => {
			if (response.isNewVariant) {
				this.showDialogEditTestPlan(diagnosticWork, response);
			}
			this.clearSelection();
			this.updateTable();
		});
	}

	//отображение диалогового окна с предложением перейти к редактированию плана работы
	showDialogEditTestPlan(diagnosticWork, variant) {
		$.show.dialog({
			title: "Сохранен вариант диагностической работы",
			size: "lg",
			message: "Вариант сохранен, желаете перейти к редактированию плана работы",
			variant: variant,
			buttons: [{
				label: "Да",
				action: (dialog) => this.editTestPlan(diagnosticWork, variant)
			}]
		});
	}

	//редактировать TestPlan
	editTestPlan(diagnosticWork, variant) {
		this.viewReady = false;
		postTo("/asp/Grade/QA/TestPlan.asp",
			{
				TestPlanId: variant.testPlanId,
				SubjectId: diagnosticWork.subjectFipi.id,
				GlobalYearId: diagnosticWork.globalYearId,
				MinGrade: _.min(diagnosticWork.grades),
				ATYPE: gradeConstants.assignmentTypes.DKR, //ДКР
				Published: diagnosticWork.published
			}
		);
	}

	//удалить вариант
	delVariant(diagnosticWork, variant) {
		if (diagnosticWork.variants.length <= 1) {
			this.$dialogs.message("Нельзя удалить последний вариант для диагностической работы");
		}
		this.$http.delete("/webapi/diagnosticWorks/variants", { params: { id: variant.id } })
			.then(() => {
				this.clearSelection();
				this.successHandler("Вариант диагностической работы удален")();
			})
			.catch((response) => this.$alerts.error(
				response.data.message || "Ошибка удаления варианта диагностической работы",
				response.data.details));
	}

	alterErrorHandler(response) {
		if (response && response.data) {
			$.show.error(response.data.message || this.language.Generic.Common.kErrorMsg);
		} else {
			$.show.error(this.language.Generic.Common.kErrorMsg);
		}
	}

	successHandler(message) {
		return () => {
			this.$alerts.success(message);
			this.updateTable();
		};
	}

	updateTable() {
		this.$appLoader.show();
		this.loader.getDiagnosticWorks(this.data.globalYear ? this.data.globalYear.id : null, this.data.subject ? this.data.subject.id : null, this.data.testLevel ? this.data.testLevel.id: null)
			.then((response) => {
					this.data.diagnosticWorks = angular.copy(response.data);
					this.data.variants = [];
					if (response.data.length > 0) {
						let variantIndex = 0;
						let diagnosticWorkIndex = 0;

						// подготовка данных по диагностическим работам для отображения
						_.each(this.data.diagnosticWorks,
							(diagnosticWork) => {
								diagnosticWork.testLevelName = this.data.testLevelsDictionary[diagnosticWork.testLevel];

								// форматирование дат
								let formattedStartDay = dateUtils.date2str(new Date(diagnosticWork.startDay));
								let formattedEndDay = null;

								if (diagnosticWork.endDay) {
									formattedEndDay = dateUtils.date2str(new Date(diagnosticWork.endDay));
								}
								
								if (formattedEndDay) {
									diagnosticWork.date = `${formattedStartDay} - ${formattedEndDay}`;
								}
								else {
									diagnosticWork.date = formattedStartDay;
								}

								// приведение массива параллелей к строке
								diagnosticWork.gradesForShow = diagnosticWork.grades.join(", ");
								_.each(diagnosticWork.variants,
									(variant, index) => {
										variant.isFirstVariant = (index === 0);
										diagnosticWorkIndex = diagnosticWorkIndex + 1;
										variant.diagnosticWorkIndex = diagnosticWorkIndex;
										variant.diagnosticWork = diagnosticWork;
										variant.index = variantIndex;
										this.data.variants.push(variant);
										variantIndex = variantIndex + 1;
									});
							});
						this.tableReady = true;
						this.$appLoader.hide();
						return;
					}
					else {
						this.tableReady = false;
						this.$appLoader.hide();
						return;
					}
				}
			)
			.catch((error) => this.defaultHandler(error));
		return;
	}

}

class DiagnosticWork {
	constructor() {
		this.id = 0;
		this.name = "";
		this.globalYearId = null;
		this.subjectFipi = null;
		this.startDay = null;
		this.endDay = null;
		this.grades = [];
		this.variants = [];
		this.emId = null;
		this.published = false;
	}
}

class Variant {
	constructor() {
		this.diagnosticWork = { id: 0, name: "" };
		this.id = 0;
		this.name = '';
		this.testPlanId = null;
		this.schools = [];
		this.appointedType = { id: -1 };
		this.testTasksAmount = 0;
	}
}


DiagnosticWorksListCtrl.$inject = ["pageContext", "$appLoader", "$http", "$alerts", "$uibModal", "$longWork", "$dialogs", "$q", "settingsProvider"];
module.exports = { DiagnosticWorksListCtrl };


