declare var dateUtils: any;
declare var angular: ng.IAngularStatic;
declare var dateInput: any;

interface DateInputOptions {
	calendarMinDate?: Date,
	calendarMaxDate?: Date,
	calendarSettings?: any,
	datePickerOptions?: any;
}

class BaseDateInputController {
	// настройки для date-range
	public startDate: string;
	public endDate? : string;

	public dateChange? : () => void;

	public options?: DateInputOptions;

	// поля компоненты
	protected datePickerContainer: JQuery<HTMLElement>;

	/*@ngInject*/
	constructor(protected $scope: ng.IScope, protected $element: JQuery<HTMLElement>, public language) {
	}

	$onInit() {
		this.options = this.options || {};

		// элемент, содержащий календарь
		this.setDatePickerContainer();

		// инициализация календаря
		this.initDatepickerComponent(this.datePickerContainer, this.options);
		// инициализация инпутов календаря
		this.setInputValues();
		// построение событий на инпутах
		this.buildEvents();
	}

	setDatePickerContainer() {
		this.datePickerContainer = this.$element.find(".input-group");
	}

	initDatepickerComponent(component: any, options: any) {
		dateInput.initDateInput(component,
			options.calendarMinDate || null,
			options.calendarMaxDate || null,
			options.calendarSettings || null,
			options.datePickerOptions || null, true);
	}

	setInputValues() {
 	}
	 
	buildEvents() {
	}

	changeDate(event: any) {
		let target = event.target;

		if (this.focused(target)) {
			return;
		}

		let date = dateUtils.str2date(target.value);

		let nsDateModel = this.getNsDateModel(target);
		if (date) {
			this.setNsDateModelValue(nsDateModel, date.toISOString());
		}
		else {
			this.setNsDateModelValue(nsDateModel, null);
			target.$invalid = true;
		}

		this.$scope.$apply();

		if (this.dateChange && typeof this.dateChange === "function") {
			this.dateChange();
		}
	}

	focused(target: any) {
		let inputElement = <HTMLInputElement>document.activeElement;

		if (inputElement) {
			return inputElement.name === target.name;
		}
		return false;
	}

	watch(element: any, newVal: string) {
		if (newVal) {
			let strDate = dateUtils.date2str(new Date(newVal));
			element.value = strDate;
		}
	}

	getNsDateModel(input: any) {
		return input.getAttribute("ns-date-model");
	}

	getNsDateModelValue(nsDateModel: string) {
		return this.$scope.$eval(nsDateModel);
	}

	setNsDateModelValue(nsDateModel: string, newVal: string) {
		this.$scope.$eval(`${nsDateModel} = newVal`, { newVal: newVal });
	}
}

class EditDateRangeController extends BaseDateInputController {
	private inputs;

	/*@ngInject*/
	constructor(protected $scope: ng.IScope, protected $element: JQuery<HTMLElement>, public language) {
		super($scope, $element, language);

		this.inputs = this.$element.find("input");
	}

	setInputValues() {
		this.inputs.toArray().map((input) => {
			// модель
			let nsDateModel = this.getNsDateModel(input);
			// значение модели
			let date = this.getNsDateModelValue(nsDateModel);

			if (date) {
				let strDate = dateUtils.date2str(new Date(date));
				let element: any = angular.element(input);

 				let elementDatepicker = this.getElementDatePicker(element);
 				if (elementDatepicker) {
 					elementDatepicker.setDate(strDate);
 				}
 			}
 		});
 	}

 	getElementDatePicker(element): any {
		 return element.data().datepicker || element.parent().data().datepicker;
	}
	 
	buildEvents() {
		let changeDateHandler = this.changeDate.bind(this);

		this.inputs.on("changeDate", changeDateHandler);
		this.inputs.on("blur", changeDateHandler);

		this.inputs.toArray().map((input) => {
			// модель
			let nsDateModel = this.getNsDateModel(input);
			this.$scope.$watch(nsDateModel, (newVal: string) => this.watch(input, newVal));
		});
	}
}

export const EditDateRangeComponent = {
	templateUrl: "/static/dist/app/global/templates/editDateRange.html",
	controller: EditDateRangeController,
	bindings: {
		startDate: "=",
		endDate: "=",
		dateChange: "&?",
		options: "="
	}
}

class EditDateInputController extends BaseDateInputController {
	public name?: string; // название инпута
	public isRequired?: boolean; // Для валидации - обязательность заполнения

	/*@ngInject*/
	constructor($scope, $element, language) {
		super($scope, $element, language);

		this.name = this.name || "date";
		this.isRequired = this.isRequired || false;
	}

	buildEvents() {
		let changeDateHandler = this.changeDate.bind(this);

		this.$element.find('div.input-group.date').on("changeDate", changeDateHandler);
		this.$element.find('input.date-input').on("blur", changeDateHandler);

		let changedDateInput = this.$element.find('input').get(0);

		let nsDateModel = this.getNsDateModel(changedDateInput);
		this.$scope.$watch(nsDateModel, (newVal: string) => this.watch(changedDateInput, newVal));
	}

	changeDate(event: any) {
		let changedDateInput: any = this.getChangedDateInput(event.target);

		if (this.focused(changedDateInput)) {
			return;
		}

		let date = dateUtils.str2date(changedDateInput.value);

		let nsDateModel = this.getNsDateModel(changedDateInput);
		if (date) {
			this.setNsDateModelValue(nsDateModel, date.toISOString());
		}
		else {
			this.setNsDateModelValue(nsDateModel, null);
			changedDateInput.$invalid = true;
		}

		this.$scope.$apply();

		if (this.dateChange && typeof this.dateChange === "function") {
			this.dateChange();
		}
	}

	getChangedDateInput(target) {
		let targetElement = angular.element(target);

		if (targetElement.is('input')) {
			return targetElement.get(0);
		}

		// если обработчик сработал на другом элементе, изменить нужно значение у инпута
		return targetElement.parent().find('input').get(0);
	}
}

export const EditDateInputComponent = {
	templateUrl: "/static/dist/app/global/templates/editDateInput.html",
	selector: "editDateInput",
	controller: EditDateInputController,
	bindings: {
		startDate: "=date",
		options: "=?",
		dateChange: "&?",
		name: "=?",
		isRequired: "=?" // обязательность заполнения
	}
}


